import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())

logging_config_template = '''
#### BEGIN LOGGING CONFIG #######
#$$LC_CLEAR_ALL
{logging_configuration}
#$$LC_END
#$$START_LOGGING
#### END LOGGING CONFIG ######
'''

logging_configuration = '''
#$$LC_UE_GROUP "{ue_group_name}" "{ue_group_ids_list}"
#$$LC_ITM 0 {enable_manual} 0 Manual  
{measurement_groups_template}
#$$LC_ITM 0 {enable_auto} 0 Automatic
'''

measurement_groups_template = '''
#$$LC_GRP 0 {enable_meas} 0 {no_reports_per_sec} 0 0 0 {measurement_group_name}
{measurement_category_template}'''

measurement_category_template = '''
#$$LC_CAT {category_id} {enable_cat} 0 0'''


class LoggingConfigScript(object):
    """TMA script for generating TM500 logging commands"""

    def __init__(self, log_config_dict):
        """

        :param log_config_dict: A dictionary with the details of measurement configuration to be enabled
        """
        self.lc_dict = log_config_dict
        self.default_log_script_values = {"ue_group_name": "*",
                                          "ue_group_ids_list": "0",
                                          "enable_manual": "0",
                                          "enable_auto": "1",
                                          "measurement_groups_template": ""
                                          }

    def __str__(self):
        return logging_config_template.format(
            logging_configuration=self.generate_logging_configuration())

    def build_default_logging_script(self):
        return logging_configuration.format(**self.default_log_script_values)

    def generate_logging_configuration(self):
        logging_script = ""
        automatic_logging = False
        if len(self.lc_dict) > 0:
            for ue_group in self.lc_dict.keys():
                try:
                    logging_script += logging_configuration.format(
                        ue_group_name=ue_group,
                        ue_group_ids_list=self.lc_dict[ue_group]["ids_list"],
                        enable_manual=int(
                            self.lc_dict[ue_group]["manual_enabled"]),
                        measurement_groups_template=self.generate_measurement_configuration(
                            self.lc_dict[ue_group]["meas_list"],
                            self.lc_dict[ue_group]["manual_enabled"]),
                        enable_auto=int(automatic_logging))
                except (KeyError, TypeError) as e:
                    logger.error(
                        "Error reading input values:%r. Will return default log script" % e)
                    logging_script += self.build_default_logging_script()
        else:
            logging_script += self.build_default_logging_script()

        return logging_script.strip()

    def generate_measurement_configuration(self, measurement_list,
                                           manual_meas_enabled=True):
        meas_script = ""
        if manual_meas_enabled:
            for meas in measurement_list:
                meas_script += measurement_groups_template.format(
                    enable_meas=int(meas["enabled"]),
                    no_reports_per_sec=meas["reports_per_sec"],
                    measurement_group_name=meas["meas_name"],
                    measurement_category_template=self.generate_meas_category_configuration(
                        meas["cat_list"]))
        return meas_script.strip()

    def generate_meas_category_configuration(self, category_list):
        cat_script = ""
        for cat in category_list:
            cat_script += measurement_category_template.format(
                category_id=cat["cat_id"],
                enable_cat=int(cat["enabled"]))
        return cat_script.strip()

    def __add__(self, other):
        return str(self) + str(other)

    def __radd__(self, other):
        return str(other) + str(self)
